 const facets=[['Mathematics is the study of topics such as quantity, structure, space, and change.',['reference','zero-order','place-value','difference','equal-groups','signed-number','fraction','equivalent-fraction','decimal-place','proportion','variable','equation','distributive-structure','sets','function','coordinate','shape','area','interval-rate','cycle']],['the identification of patterns and formulating new conjectures based on them.',['logical-claim','pattern','conjecture','cycle']],['prove the truth or falsity of these conjectures.',['logical-claim','counterexample','proof','cycle']],['There are many fields of mathematics, some of which are widely used for practical applications.',['chance-model','statistical-evidence','fields-applications','cycle']]]
 const mapping=registerServiceGroup(dataset,'mathematics',keys,facets,{uuid,activityId:id}).mapping
 for(const spec of specs)authorProfessionActivity(dataset,{...spec,id:id(spec.key),supporting_sources:[{title:'ESCO 1.2.1: mathematics knowledge scope, separate from specialised applied calculation competence',url:mapping.skill_id},{title:'OpenStax Contemporary Mathematics: open textbook topic reference; examples and sequencing here are individually authored proposals',url:'https://openstax.org/books/contemporary-mathematics/pages/index'}]})
 for(const to of mapping.activity_ids)if(!dataset.decompositions.some(edge=>edge.type==='decomposes_into'&&edge.from===mapping.skill_id&&edge.to===to))dataset.decompositions.push({from:mapping.skill_id,to,type:'decomposes_into',completion_requirement:'required',validation:'proposed',source:professionSource})
